import java.util.*;

public class Solver {
    static final long MOD = 1000000007L;
    static final int LIM = 1 << 20;

    int n, m;
    long[] cnt = new long[LIM];
    long[] cnt2 = new long[LIM];
    long[][] a;
    int[] rev = new int[LIM];
    int[] rev2 = new int[LIM];

    long modpow(long x, long p) {
        long r = 1;
        while (p > 0) {
            if ((p & 1) == 1) r = r * x % MOD;
            x = x * x % MOD;
            p >>= 1;
        }
        return r;
    }

    // next permutation in lexicographic order, returns true if exists
    boolean nextPermutation(List<Integer> list) {
        int i = list.size() - 2;
        while (i >= 0 && list.get(i) >= list.get(i + 1)) i--;
        if (i < 0) return false;
        int j = list.size() - 1;
        while (list.get(j) <= list.get(i)) j--;
        Collections.swap(list, i, j);
        Collections.reverse(list.subList(i + 1, list.size()));
        return true;
    }

    void dfs1(int cur, List<Integer> con, long prob) {
        if (cur == m) {
            int nxt = 0, id = 0;
            for (int j = 0; j < (1 << n); ++j) {
                if (Integer.bitCount(j) != m) continue;
                List<Integer> vi = new ArrayList<>();
                for (int i = 0; i < n; ++i) if ((j >> i & 1) == 1) vi.add(i);
                int ok = 0;
                // vi is initially sorted
                do {
                    boolean good = true;
                    for (int x = 0; x < m; ++x) {
                        if (((con.get(x) >> vi.get(x)) & 1) == 0) {
                            good = false;
                            break;
                        }
                    }
                    if (good) {
                        ok = 1;
                        break;
                    }
                } while (nextPermutation(vi));
                if (ok == 1) id |= (1 << nxt);
                ++nxt;
            }
            cnt[id] += prob;
            return;
        }
        for (int j = 0; j < (1 << n); ++j) {
            con.add(j);
            long nw = prob;
            for (int k = 0; k < n; ++k) {
                if ((j >> k & 1) == 1)
                    nw = nw * a[cur][k] % MOD;
                else
                    nw = nw * (MOD + 1 - a[cur][k]) % MOD;
            }
            dfs1(cur + 1, con, nw);
            con.remove(con.size() - 1);
        }
    }

    void dfs2(int cur, List<Integer> con, long prob) {
        if (cur == n) {
            int nxt = 0, id = 0;
            for (int j = 0; j < (1 << n); ++j) {
                if (Integer.bitCount(j) != n - m) continue;
                List<Integer> vi = new ArrayList<>();
                for (int i = 0; i < n; ++i) if ((j >> i & 1) == 1) vi.add(i);
                int ok = 0;
                do {
                    boolean good = true;
                    for (int x = 0; x < n - m; ++x) {
                        if (((con.get(x) >> vi.get(x)) & 1) == 0) {
                            good = false;
                            break;
                        }
                    }
                    if (good) {
                        ok = 1;
                        break;
                    }
                } while (nextPermutation(vi));
                if (ok == 1) id |= (1 << nxt);
                ++nxt;
            }
            cnt2[id] += prob;
            return;
        }
        for (int j = 0; j < (1 << n); ++j) {
            con.add(j);
            long nw = prob;
            for (int k = 0; k < n; ++k) {
                if ((j >> k & 1) == 1)
                    nw = nw * a[cur][k] % MOD;
                else
                    nw = nw * (MOD + 1 - a[cur][k]) % MOD;
            }
            dfs2(cur + 1, con, nw);
            con.remove(con.size() - 1);
        }
    }

    void solve() {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        a = new long[n][n];
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                long val = sc.nextLong();
                a[i][j] = val * modpow(100L, MOD - 2) % MOD;
                a[i][j] = (a[i][j] % MOD + MOD) % MOD;
            }
        }
        if (n == 1) {
            System.out.println(a[0][0]);
            return;
        }
        m = n / 2;

        dfs1(0, new ArrayList<>(), 1);
        for (int i = 0; i < LIM; ++i) cnt[i] %= MOD;
        for (int i = 0; i < 20; ++i) {
            for (int j = 0; j < LIM; ++j) {
                if ((j >> i & 1) == 1) {
                    cnt[j] += cnt[j ^ (1 << i)];
                    cnt[j] %= MOD;
                }
            }
        }
        long all = cnt[LIM - 1];

        dfs2(m, new ArrayList<>(), 1);
        for (int i = 0; i < LIM; ++i) cnt2[i] %= MOD;

        Arrays.fill(rev, -1);
        int nd = 0;
        for (int i = 0; i < (1 << n); ++i) {
            if (Integer.bitCount(i) == m) rev[i] = nd++;
        }

        Arrays.fill(rev2, -1);
        nd = 0;
        int[] cor = new int[25];
        for (int i = 0; i < (1 << n); ++i) {
            if (Integer.bitCount(i) == n - m) {
                cor[nd] = rev[(1 << n) - 1 - i];
                rev2[i] = nd++;
            }
        }

        long ans = 0;
        for (int i = 0; i < (1 << nd); ++i) {
            long cur = cnt2[i];
            int mask = 0;
            for (int j = 0; j < nd; ++j) {
                if (((i >> j) & 1) == 0) mask += (1 << cor[j]);
            }
            ans += cur * (all - cnt[mask]) % MOD;
        }
        System.out.println((ans % MOD + MOD) % MOD);
    }

    public static void main(String[] args) {
        new Solver().solve();
    }
}
